import * as THREE from 'three';import {PLAZA} from '../plaza/layout.js';import {createToyKit,disposeToyTree} from '../world/toy-kit.js';import {marshmallowPoseFrame,createMarshmallowPose} from './pose.js';
const Y=new THREE.Vector3(0,1,0),v=new THREE.Vector3(),clamp=n=>Math.max(0,Math.min(1,n));
export function browningColor(value){const white=new THREE.Color('#fff6de'),gold=new THREE.Color('#dca85d'),brown=new THREE.Color('#895032'),char=new THREE.Color('#47362e');return value<.65?white.lerp(gold,clamp(value/.65)):value<1.1?gold.lerp(brown,clamp((value-.65)/.45)):brown.lerp(char,clamp((value-1.1)/.45));}
function foodGeometry(){const points=[new THREE.Vector2(0,-.17),new THREE.Vector2(.10,-.165),new THREE.Vector2(.133,-.14),new THREE.Vector2(.142,-.105),new THREE.Vector2(.142,.105),new THREE.Vector2(.133,.14),new THREE.Vector2(.10,.165),new THREE.Vector2(0,.17)],g=new THREE.LatheGeometry(points,32);g.setAttribute('color',new THREE.BufferAttribute(new Float32Array(g.attributes.position.count*3),3));return g;}
export function createMarshmallowView({zoneRoot,player,model,poser}){
 const saved={parent:player.parent,p:player.position.clone(),q:player.quaternion.clone(),s:player.scale.clone(),mp:model.position.clone(),mq:model.quaternion.clone(),ms:model.scale.clone(),children:player.children.map(o=>[o,o.visible])};
 const root=new THREE.Group();root.name='marshmallow.session';zoneRoot.add(root);const pose=createMarshmallowPose(model,poser),seat=PLAZA.roasting??{seatTop:.48,anchor:{x:PLAZA.fire.x+1.8,z:PLAZA.fire.z+.7,yaw:Math.atan2(-1.8,-.7)}};zoneRoot.add(player);player.position.set(seat.anchor.x,seat.seatTop-pose.seatY,seat.anchor.z);player.rotation.set(0,seat.anchor.yaw,0);player.scale.setScalar(1);model.position.set(0,0,0);model.quaternion.identity();model.scale.setScalar(1);for(const[c]of saved.children)if(c!==model)c.visible=false;
 const {cylinder,mat}=createToyKit(root),stool=new THREE.Group();stool.name='marshmallow.roasting-stool';stool.position.set(seat.anchor.x,0,seat.anchor.z);stool.rotation.y=seat.anchor.yaw;root.add(stool);const top=new THREE.Mesh(new THREE.BoxGeometry(.86,.09,.50),mat('#bc9e70'));top.position.y=seat.seatTop-.045;top.castShadow=top.receiveShadow=true;stool.add(top);for(const x of [-.31,.31])for(const z of [-.16,.16]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.035,.045,seat.seatTop-.135,8),mat('#8d7b5e'));leg.position.set(x,(seat.seatTop-.135)/2+.045,z);leg.castShadow=leg.receiveShadow=true;stool.add(leg);}const stick=cylinder(.014,.017,1.13,'#b59160',0,0,0);stick.name='marshmallow.skewer';const food=new THREE.Mesh(foodGeometry(),new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));food.name='marshmallow.food';root.add(food);
 const camera=new THREE.OrthographicCamera(-3,3,2,-2,.05,90),center=new THREE.Vector3(PLAZA.fire.x+1,.93,PLAZA.fire.z+.3),eye=new THREE.Vector3(PLAZA.fire.x-2.9,3.5,PLAZA.fire.z+4.2);zoneRoot.updateWorldMatrix(true,true);camera.position.copy(zoneRoot.localToWorld(eye));camera.lookAt(zoneRoot.localToWorld(center.clone()));
 let alive=true,current=null,frame=null,framePoints=[],grip=new THREE.Vector3(),tip=new THREE.Vector3(),base=new THREE.Vector3(),direction=new THREE.Vector3(),lastPose='';
 const localToRoot=p=>root.worldToLocal(player.localToWorld(p));
 function update(s){if(!alive)return;current=s;const quantized={...s,elapsed:Math.floor(s.elapsed*24)/24};frame=marshmallowPoseFrame(quantized);const key=JSON.stringify(frame.hands);if(key!==lastPose){pose.update(frame);lastPose=key;}player.updateWorldMatrix(true,true);root.updateWorldMatrix(true,true);
  grip.fromArray(frame.hands.right);direction.fromArray(frame.direction);tip.copy(grip).addScaledVector(direction,frame.gripToTip);base.copy(tip).addScaledVector(direction,-1.13);const mid=base.clone().add(tip).multiplyScalar(.5);stick.position.copy(localToRoot(mid));const worldDirection=direction.clone().applyQuaternion(player.quaternion);stick.quaternion.setFromUnitVectors(Y,worldDirection);food.position.copy(localToRoot(tip.clone()));food.quaternion.copy(stick.quaternion).multiply(new THREE.Quaternion().setFromAxisAngle(Y,s.angle));food.scale.setScalar(frame.foodScale);food.visible=frame.foodScale>.001;
  const attr=food.geometry.attributes.color,pos=food.geometry.attributes.position;for(let i=0;i<attr.count;i++){const angle=(Math.atan2(pos.getX(i),pos.getZ(i))+Math.PI*2)%(Math.PI*2),side=Math.floor((angle+Math.PI/4)%(Math.PI*2)/(Math.PI/2)),color=browningColor(s.browning[side]);attr.setXYZ(i,color.r,color.g,color.b);}attr.needsUpdate=true;
  framePoints=[[-.63,0,-.35],[.63,1.65,.43],base.toArray(),tip.toArray()].map(p=>player.localToWorld(new THREE.Vector3(...p)).toArray());framePoints.push(zoneRoot.localToWorld(new THREE.Vector3(PLAZA.fire.x-.9,0,PLAZA.fire.z-.9)).toArray(),zoneRoot.localToWorld(new THREE.Vector3(PLAZA.fire.x+.9,1.1,PLAZA.fire.z+.9)).toArray());
 }
 function clearance(point){return new THREE.Line3(base,tip).closestPointToPoint(new THREE.Vector3(...point),true,v).distanceTo(new THREE.Vector3(...point));}
 return {root,camera,update,fit(w,h){const aspect=Math.max(.25,w/h),span=Math.max(3.5,4.8/aspect);camera.left=-span*aspect/2;camera.right=span*aspect/2;camera.top=span/2;camera.bottom=-span/2;camera.updateProjectionMatrix();},snapshot:()=>({stickLength:base.distanceTo(tip),handContactError:new THREE.Line3(base,tip).closestPointToPoint(grip,true,v).distanceTo(grip),skewerShoulderClearance:clearance([.38,.685,.025]),skewerFaceClearance:clearance([0,.9,.43]),marshmallowScale:food.scale.x,framePoints,hand:grip.toArray(),tip:tip.toArray(),base:base.toArray()}),dispose(){if(!alive)return;alive=false;pose.dispose();saved.parent?.add(player);player.position.copy(saved.p);player.quaternion.copy(saved.q);player.scale.copy(saved.s);model.position.copy(saved.mp);model.quaternion.copy(saved.mq);model.scale.copy(saved.ms);for(const[o,visible]of saved.children)o.visible=visible;disposeToyTree(root);}};
}
